def transform(grid):
    from collections import Counter
    h, w = len(grid), len(grid[0])
    counts = Counter(x for row in grid for x in row)
    background = counts.most_common(1)[0][0]
    color = next(x for x in counts if x != background and x != 0)
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    forms = set()
    for reflect in (False, True):
        for rot in range(4):
            q = []
            for r, c in points:
                x, y = (r, -c) if reflect else (r, c)
                for _ in range(rot):
                    x, y = y, -x
                q.append((x, y))
            mr, mc = min(r for r, c in q), min(c for r, c in q)
            forms.add(tuple(sorted((r-mr, c-mc) for r, c in q)))
    out = [row[:] for row in grid]
    for shape in forms:
        sh, sw = max(r for r, c in shape)+1, max(c for r, c in shape)+1
        for r0 in range(h-sh+1):
            for c0 in range(w-sw+1):
                cells = [(r0+r, c0+c) for r, c in shape]
                if all(grid[r][c] == 0 for r, c in cells):
                    for r, c in cells:
                        out[r][c] = color
    return out
